from bs4 import BeautifulSoup

with open('/tmp/nvda-20260125.htm', 'r', encoding='utf-8', errors='ignore') as f:
    html = f.read()

soup = BeautifulSoup(html, 'html.parser')

all_p = soup.find_all(['div', 'p'])
in_section = False
current_cat = None
categories = {}

for el in all_p:
    text = el.get_text().strip()
    if text == 'Item 1A. Risk Factors':
        in_section = True
        continue
    if in_section:
        if text == 'Item 1B. Unresolved Staff Comments':
            break
        for s in el.find_all('span'):
            style = s.get('style', '')
            stext = s.get_text().strip()
            if not stext:
                continue
            if 'color:#76b900' in style and 'font-weight:700' in style:
                current_cat = stext
                if current_cat not in categories:
                    categories[current_cat] = []
            elif 'font-weight:700' in style:
                # Avoid duplicate spans inside same p
                if current_cat and (not categories[current_cat] or categories[current_cat][-1] != stext):
                    categories[current_cat].append(stext)

for cat, items in categories.items():
    print(f'=== Category: {cat} ({len(items)} items) ===')
    for idx, item in enumerate(items, 1):
        print(f'  {idx}. {item}')
